    payload = {
        "format": FORMAT,
        "key_id": key_id,
        "version": version,
        "algorithm": algorithm,
        "enc": ENC_AES_GCM,
        "wrap": wrap,
        "nonce": b64_encode(nonce),
        "tag": b64_encode(tag),
        "ciphertext": b64_encode(ciphertext),
        "wrapped_key": b64_encode(wrapped_key),
        "aad": b64_encode(aad),
    }
