def wrap_data_key(algorithm: str, kek, data_key: bytes) -> tuple:
    """Wrap a caller-supplied 32-byte data key under the KEK (export path).

    The in-memory export counterpart of a KMS/HSM-native ``wrap_key``: the
    KEK is the raw 32-byte key for AES256 or a loaded 2048-bit RSA private key
    for RSA2048 (its public component wraps the data key). Returns
    ``(wrapped_key, wrap_nonce)`` -- a 48-byte AES-256-GCM sealed key plus a
    12-byte nonce for AES256, or a 256-byte RSA-OAEP-SHA256 sealed key plus
    ``None`` for RSA2048.
    """
    return _wrap_dek_with(algorithm, kek, data_key)


def unwrap_data_key(
    algorithm: str, kek, wrapped_key: bytes,
    wrap_nonce: Optional[bytes],
) -> bytes:
    """Recover a wrapped 32-byte data key using the KEK (export path).

    The in-memory export counterpart of a KMS/HSM-native ``unwrap_key``. A
    failed AES-GCM authentication or RSA unpadding is one field-naming
    :class:`EnvelopeError` (``field wrapped_key``); the recovered data key
    exists only in process memory for the duration of the call.
    """
    try:
        if algorithm == _AES256:
            if not isinstance(kek, (bytes, bytearray)) or len(kek) != _KEY_LEN:
                raise EnvelopeError(
                    "server key material is invalid for AES256"
                )
            if wrap_nonce is None:
                raise InvalidTag("missing wrap nonce")
            return AESGCM(bytes(kek)).decrypt(wrap_nonce, wrapped_key, None)
        if algorithm == _RSA2048:
            if not isinstance(kek, rsa.RSAPrivateKey) or kek.key_size != 2048:
                raise EnvelopeError(
                    "server key material is invalid for RSA2048"
                )
            return kek.decrypt(wrapped_key, _OAEP)
    except InvalidTag as exc:
        raise EnvelopeError(
            "field wrapped_key is tampered or cannot be authenticated"
        ) from exc
    except ValueError as exc:
        raise EnvelopeError(
            "field wrapped_key is tampered or cannot be authenticated"
        ) from exc
    raise EnvelopeError(
        "field wrapped_key is tampered or cannot be authenticated"
    )


